def check_constraints(x2):
    # 1. Calculate x3 required by C3:
    # x3 = 48*x2^2 / (29*x2 - 144)

    denominator = 29 * x2 - 144

    # Check positivity for x3
    if denominator <= 0:
        return None, None

    numerator = 48 * x2**2

    # Check if x3 is an integer
    if numerator % denominator != 0:
        return None, None

    x3 = numerator // denominator

    # 2. Check C2: x3 >= 1 + (x2^3 - x2^2) / 3
    required_x3 = 1 + (x2**3 - x2**2) / 3

    if x3 >= required_x3:
        return x2, x3
    else:
        return None, None

# Search for solutions starting from x2 = 5
solutions = []
MAX_X2 = 100 

for x2 in range(5, MAX_X2 + 1):
    x2_sol, x3_sol = check_constraints(x2)
    if x2_sol is not None:
        solutions.append((x2_sol, x3_sol))

print("Solutions found (x2, x3):")
if solutions:
    for sol in solutions:
        print(sol)
